static int **result;
static int resultLen;

static bool dfs(int **g, int r, int c, int rows, int cols, bool **visited) {
  if (r >= rows || c >= cols || g[r][c] == 1 || visited[r][c]) return false;
  visited[r][c] = true;
  if ((r == rows - 1 && c == cols - 1) || dfs(g, r + 1, c, rows, cols, visited) ||
      dfs(g, r, c + 1, rows, cols, visited)) {
    result[resultLen] = (int *)malloc(sizeof(int) * 2);
    result[resultLen][0] = r;
    result[resultLen][1] = c;
    resultLen++;
    return true;
  }
  return false;
}

int **pathWithObstacles(int **obstacleGrid, int obstacleGridSize, int *obstacleGridColSize, int *returnSize, int **returnColumnSizes) {
  int rows = obstacleGridSize, cols = obstacleGridColSize[0];
  result = (int **)malloc(sizeof(int *) * (rows + cols));
  resultLen = 0;
  bool **visited = (bool **)malloc(sizeof(bool *) * rows);
  for (int i = 0; i < rows; i++) visited[i] = (bool *)calloc(cols, sizeof(bool));
  bool found = dfs(obstacleGrid, 0, 0, rows, cols, visited);
  for (int i = 0; i < rows; i++) free(visited[i]);
  free(visited);
  if (!found) {
    *returnSize = 0;
    *returnColumnSizes = NULL;
    free(result);
    return NULL;
  }
  for (int i = 0; i < resultLen / 2; i++) {
    int *t = result[i];
    result[i] = result[resultLen - 1 - i];
    result[resultLen - 1 - i] = t;
  }
  *returnSize = resultLen;
  *returnColumnSizes = (int *)malloc(sizeof(int) * resultLen);
  for (int i = 0; i < resultLen; i++) (*returnColumnSizes)[i] = 2;
  return result;
}

class Solution {
  bool dfs(vector<vector<int>> &g, int r, int c, vector<vector<bool>> &visited, vector<vector<int>> &path) {
    if (r >= (int)g.size() || c >= (int)g[0].size() || g[r][c] == 1 || visited[r][c]) return false;
    visited[r][c] = true;
    if ((r == (int)g.size() - 1 && c == (int)g[0].size() - 1) || dfs(g, r + 1, c, visited, path) ||
        dfs(g, r, c + 1, visited, path)) {
      path.push_back({r, c});
      return true;
    }
    return false;
  }

public:
  vector<vector<int>> pathWithObstacles(vector<vector<int>> &obstacleGrid) {
    int rows = obstacleGrid.size(), cols = obstacleGrid[0].size();
    vector<vector<bool>> visited(rows, vector<bool>(cols, false));
    vector<vector<int>> path;
    if (!dfs(obstacleGrid, 0, 0, visited, path)) return {};
    reverse(path.begin(), path.end());
    return path;
  }
};

func pathWithObstacles(obstacleGrid [][]int) [][]int {
	rows, cols := len(obstacleGrid), len(obstacleGrid[0])
	visited := make([][]bool, rows)
	for i := range visited {
		visited[i] = make([]bool, cols)
	}
	var path [][]int
	var dfs func(r, c int) bool
	dfs = func(r, c int) bool {
		if r >= rows || c >= cols || obstacleGrid[r][c] == 1 || visited[r][c] {
			return false
		}
		visited[r][c] = true
		if (r == rows-1 && c == cols-1) || dfs(r+1, c) || dfs(r, c+1) {
			path = append(path, []int{r, c})
			return true
		}
		return false
	}
	if !dfs(0, 0) {
		return [][]int{}
	}
	for i, j := 0, len(path)-1; i < j; i, j = i+1, j-1 {
		path[i], path[j] = path[j], path[i]
	}
	return path
}

class Solution {
  private boolean dfs(int[][] g, int r, int c, boolean[][] visited, List<List<Integer>> path) {
    if (r >= g.length || c >= g[0].length || g[r][c] == 1 || visited[r][c]) return false;
    visited[r][c] = true;
    if ((r == g.length - 1 && c == g[0].length - 1) || dfs(g, r + 1, c, visited, path)
        || dfs(g, r, c + 1, visited, path)) {
      path.add(Arrays.asList(r, c));
      return true;
    }
    return false;
  }

  public List<List<Integer>> pathWithObstacles(int[][] obstacleGrid) {
    int rows = obstacleGrid.length, cols = obstacleGrid[0].length;
    boolean[][] visited = new boolean[rows][cols];
    List<List<Integer>> path = new ArrayList<>();
    if (!dfs(obstacleGrid, 0, 0, visited, path)) return new ArrayList<>();
    Collections.reverse(path);
    return path;
  }
}

class Solution:
    def pathWithObstacles(self, obstacleGrid: List[List[int]]) -> List[List[int]]:
        rows, cols = len(obstacleGrid), len(obstacleGrid[0])
        visited = [[False] * cols for _ in range(rows)]
        path = []

        def dfs(r: int, c: int) -> bool:
            if r >= rows or c >= cols or obstacleGrid[r][c] == 1 or visited[r][c]:
                return False
            visited[r][c] = True
            if (r == rows - 1 and c == cols - 1) or dfs(r + 1, c) or dfs(r, c + 1):
                path.append([r, c])
                return True
            return False

        if not dfs(0, 0):
            return []
        path.reverse()
        return path

impl Solution {
  pub fn path_with_obstacles(obstacle_grid: Vec<Vec<i32>>) -> Vec<Vec<i32>> {
    let rows = obstacle_grid.len();
    let cols = obstacle_grid[0].len();
    let mut visited = vec![vec![false; cols]; rows];
    let mut path: Vec<Vec<i32>> = vec![];
    fn dfs(
      g: &Vec<Vec<i32>>,
      r: usize,
      c: usize,
      visited: &mut Vec<Vec<bool>>,
      path: &mut Vec<Vec<i32>>,
    ) -> bool {
      if r >= g.len() || c >= g[0].len() || g[r][c] == 1 || visited[r][c] {
        return false;
      }
      visited[r][c] = true;
      if (r == g.len() - 1 && c == g[0].len() - 1)
        || dfs(g, r + 1, c, visited, path)
        || dfs(g, r, c + 1, visited, path)
      {
        path.push(vec![r as i32, c as i32]);
        return true;
      }
      false
    }
    if !dfs(&obstacle_grid, 0, 0, &mut visited, &mut path) {
      return vec![];
    }
    path.reverse();
    path
  }
}

const pathWithObstacles = (obstacleGrid: number[][]): number[][] => {
  const rows = obstacleGrid.length;
  const cols = obstacleGrid[0].length;
  const visited: boolean[][] = Array.from({ length: rows }, () => new Array(cols).fill(false));
  const path: number[][] = [];

  const dfs = (r: number, c: number): boolean => {
    if (r >= rows || c >= cols || obstacleGrid[r][c] === 1 || visited[r][c]) return false;
    visited[r][c] = true;
    if ((r === rows - 1 && c === cols - 1) || dfs(r + 1, c) || dfs(r, c + 1)) {
      path.push([r, c]);
      return true;
    }
    return false;
  };

  if (!dfs(0, 0)) return [];
  path.reverse();
  return path;
};
